import{z as i,x as A,o as t,c as B,q as l,j as n,D as r,d as E,s as o,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"GPU SIMT 与 warp","description":"","frontmatter":{"title":"GPU SIMT 与 warp","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-simt.md","filePath":"cs/gpu-simt.md","lastUpdated":1791063341000}'),d={name:"cs/gpu-simt.md"};function m(c,a,C,h,D,w){const s=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="gpu-simt-与-warp" tabindex="-1">GPU SIMT 与 warp <a class="header-anchor" href="#gpu-simt-与-warp" aria-label="Permalink to &quot;GPU SIMT 与 warp&quot;">​</a></h1><div class="epigraph"><p>一组线程共享同一 PC、走同一条指令，数据各异；硬件用掩码关掉分岔的人，而不是给每人一套完整的乱序核。</p><footer>—— 据 Lindholm et al., NVIDIA Tesla: A Unified Graphics and Computing Architecture, IEEE Micro 2008 整理</footer></div><p><a href="/cs/vector-lanes">上一课</a> 的 lane 由一条向量指令驱动，程序员看见的是向量寄存器。图形与数据并行负载有成千上万个「小程序实例」。本课不重讲 Cray 链式。缺口是 <strong>SIMT：把 lane 包装成线程，warp（或 wavefront）共享 PC，用线程切换藏延迟。</strong> 不是 Transformer 的注意力实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>为每个像素/每个粒子做一套 <a href="/cs/ooo-rob">ROB</a> 面积不可接受。它们的控制流大体相同。缺口不是再加 CPU 核，而是<strong>单指令多线程：32/64 个线程一拍锁步执行同一 opcode，寄存器文件按线程号分行，遇到长延迟则换另一个就绪 warp。</strong></p><p><span class="marginnote">NVIDIA 称 warp，AMD 称 wavefront。Lindholm 等描述 Tesla 统一着色器：图形与计算共用 SIMT 核。这是微结构，不是 CUDA 教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SM / CU 上驻留多个 warp。每拍选一个就绪 warp 发射（可宽发射多条）。寄存器：物理堆按线程切片，无 CPU 那种重命名密度。记分牌跟踪该 warp 的依赖；切换 warp 隐藏 cache/纹理/DRAM 延迟——这是 <a href="/cs/dataflow-dae">DAE</a> 的线程版。<span class="marginnote">切 warp 藏延迟可以想象成厨师同时看几口锅：一口锅在等汤开（访存长延迟），就转身炒另一口，灶（SM）从不闲着。CPU 乱序核相当于给每口锅配一个专职机器人厨师，贵；SIMT 是一个厨师配足够多的锅。</span></p>',8)),(t(),n(p,null,{default:r(()=>[o(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20W0%5B%22warp%200%20%E5%85%B1%E4%BA%AB%20PC%22%5D%20--%3E%20LANE%5B%22lane%20%C3%97%20%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20W1%5B%22warp%201%20%E5%B0%B1%E7%BB%AA%E7%AD%89%E5%BE%85%22%5D%20--%3E%20SEL%5B%22%E8%B0%83%E5%BA%A6%E9%80%89%20warp%22%5D%0A%20%20MISS%5B%22%E9%95%BF%E5%BB%B6%E8%BF%9F%22%5D%20--%3E%20SW%5B%22%E5%88%87%E5%88%B0%E5%85%B6%E4%BB%96%20warp%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[e("a",{href:"/cs/mlp-memory-parallelism"},"MLP"),E(" 来自大量 outstanding 线程，而不是单个 ROB。占用率：寄存器与共享存储限制同时驻留的 warp 数，切换不够则延迟暴露。与 CPU MIMD：每个 CPU 线程有独立 PC 与一致性协议；SIMT 线程默认不提供那种强独立控制流。下一课存储层次：共享存储、私有 L1、HBM。"),e("span",{class:"marginnote"},"数字实例：warp 是 32 个线程，若一个 SM 驻留 48 个 warp，就是 1536 个线程共用一套取指、译码和调度硬件——摊到每个线程的控制逻辑成本近乎为零，这就是「用面积换大量轻量上下文」那笔账的具体样子。")],-1)),(t(),n(p,null,{default:r(()=>[o(s,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%AF%8F%E7%BA%BF%E7%A8%8B%E5%AF%84%E5%AD%98%E5%99%A8%E7%94%A8%E9%87%8F%22%5D%20--%3E%20OCC%5B%22%E5%86%B3%E5%AE%9A%E5%90%8C%E6%97%B6%E9%A9%BB%E7%95%99%E7%9A%84%20warp%20%E6%95%B0%22%5D%0A%20%20SMEM%5B%22%E5%85%B1%E4%BA%AB%E5%AD%98%E5%82%A8%E5%8D%A0%E7%94%A8%22%5D%20--%3E%20OCC%0A%20%20OCC%20--%3E%7C%22%E9%A9%BB%E7%95%99%E8%B6%B3%E5%A4%9F%E5%A4%9A%22%7C%20HIDE%5B%22%E8%AE%BF%E5%AD%98%E5%BB%B6%E8%BF%9F%E8%A2%AB%E5%88%AB%E7%9A%84%20warp%20%E5%A1%AB%E6%BB%A1%22%5D%0A%20%20OCC%20--%3E%7C%22%E9%A9%BB%E7%95%99%E5%A4%AA%E5%B0%91%22%7C%20EXP%5B%22%E5%BB%B6%E8%BF%9F%E6%9A%B4%E9%9C%B2%EF%BC%9ASM%20%E9%97%B2%E7%AD%89%22%5D%0A%20%20EXP%20--%3E%20FIX%5B%22%E5%87%8F%E5%AF%84%E5%AD%98%E5%99%A8%20%2F%20%E5%87%8F%20smem%20%E6%8D%A2%E9%A9%BB%E7%95%99%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">为什么重要：占用率这一步如果算错了（比如循环里临时数组把寄存器顶爆），驻留 warp 掉到只剩一两个，切换就没有备选，前面所有「靠 warp 藏延迟」的设计同时失效——kernel 不是变慢一点，是数量级地慢。</span></p><p>分支下一课才发散；本课只钉「共享 PC + 切换」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CUDA 编程模型细则，不写注意力 kernel。不要把 SIMT 说成「很大的 AVX」。多 socket CPU 仍是 MIMD。存储层次下一课。<span class="marginnote">「SIMT 就是很大的 AVX」错在哪：AVX 是一条指令里的一串 lane，lane 没有自己的寄存器行和线程身份，更不能被单独调度挂起；SIMT 的每个 lane 是有完整寄存器行的线程，warp 之间还能独立换入换出——差的是「线程」这一层，不是宽度。</span></p><p>后课默认：GPU 核用 warp 调度藏延迟。程序员看见的 bank、shared memory 与合并，决定有效带宽。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SIMT：warp 共享 PC，lane 上跑不同线程数据，切 warp 藏延迟。</li><li>面积换大量轻量上下文，而不是每线程乱序核。</li><li>GPU 存储层次是下一课。</li><li>出处：Lindholm et al., <em>IEEE Micro</em>, 2008。</li></ul>',7))])}const S=i(d,[["render",m]]);export{u as __pageData,S as default};
